//list of pokemon

import Link from "next/link";
const list = [
  { id: 1, name: "Bulbasaur" },
  { id: 2, name: "Charmender" },
  { id: 3, name: "Squirtle" },
];
export default function Pokemonlist() {
  //const{pok}=await params
  return (
    <div className="flex">
      <h1 className="text-2xl"></h1>

      <div className="flex">
        {list.map((p) => (
          <Link key={p.id} href={`/int-par/pokemon/${p.id}/`}>
            {p.name}
          </Link>
          
        ))}
      </div>
      
    </div>
  );
}
